// Report Studio editable UI start
const STUDIO_NOTE = 'Make Monthly Report Jul Vs Aug\n- Total Spend (USD)\n- Total Impressions\n- Total Reach\n- Overall CPM (USD)\n- Page Likes (Campaign: \n- Like Page \n- Cost per Page Like (USD)\n- Messaging Conversations';
function studioDB(action, value) {
 return new Promise((resolve,reject)=>{
  const req=indexedDB.open('keovothy-report-studio',1);
  req.onupgradeneeded=()=>req.result.createObjectStore('reports',{keyPath:'id'});
  req.onerror=()=>reject(req.error);
  req.onsuccess=()=>{const db=req.result;const tx=db.transaction('reports',action==='list'?'readonly':'readwrite');const table=tx.objectStore('reports');const op=action==='list'?table.getAll():action==='save'?table.put(value):table.delete(value);let result;op.onsuccess=()=>result=op.result;tx.oncomplete=()=>{db.close();resolve(result)};tx.onerror=()=>{db.close();reject(tx.error)};tx.onabort=()=>{db.close();reject(tx.error||Error('Save aborted'))}};
 });
}
